import 'dart:convert';

import 'package:flutter/services.dart';

import '../../../core/constants/university_map_configuration.dart';
import '../data/map_package.dart';

/// Ids of style layers that app code refers to.
abstract final class MapStyleLayers {
  /// The first label layer. Route lines are inserted below it so place and
  /// road names stay readable on top of routes.
  static const String firstLabel = 'label-water-line';
}

/// Loads the app's MapLibre styles and points them at the local map data.
///
/// The style files in `assets/map_styles/` are generated by
/// `tools/map/build_styles.py`. They contain two placeholders, replaced here,
/// so the same style works wherever the map data is stored.
class MapStyleService {
  MapStyleService({required this._bundle});

  static const String basemapPlaceholder = '{{BASEMAP_URL}}';
  static const String glyphsPlaceholder = '{{GLYPHS_URL}}';

  final AssetBundle _bundle;

  static String assetFor(UniversityMapStyle style) => switch (style) {
    UniversityMapStyle.light => 'assets/map_styles/light.json',
    UniversityMapStyle.dark => 'assets/map_styles/dark.json',
  };

  /// Returns the complete style JSON for [style], ready to pass to MapLibre.
  Future<String> loadStyle(
    UniversityMapStyle style,
    MapResources resources,
  ) async {
    final template = await _bundle.loadString(assetFor(style));
    final document = jsonDecode(template);
    if (document is! Map<String, dynamic>) {
      throw const FormatException('The map style is not a JSON object.');
    }

    document['glyphs'] = resources.glyphsUrlTemplate;
    final sources = document['sources'];
    if (sources is Map<String, dynamic>) {
      for (final source in sources.values) {
        if (source is Map<String, dynamic> &&
            source['url'] == basemapPlaceholder) {
          source['url'] = resources.basemapUrl;
        }
      }
    }

    final resolved = jsonEncode(document);
    if (resolved.contains(basemapPlaceholder) ||
        resolved.contains(glyphsPlaceholder)) {
      throw const FormatException(
        'The map style still contains an unresolved placeholder.',
      );
    }
    return resolved;
  }
}
